+	require.Equal(t, 5, prompt.TokenCount()) // One content token and four message tokens.
+
+	completion, err := NewSynchronousTokenCounter("hello world")
+	require.NoError(t, err)
+	require.Equal(t, 5, completion.TokenCount())
